  get: (endpoint: string, params: Record<string, any> = {}) =>
    fetch(`${BASE_URL}${endpoint}${toQueryString(params)}`).then(r => {
      if (!r.ok) throw new Error(`API error ${r.status}`)
      return r.json()
    }),
}

